let LANG = 'en';
function t(k, v){
  const i = LANGS.findIndex(l=>l[0]===LANG), a = L[k];
  let s = a ? (a[i] || a[0]) : k;
  if(v) for(const x in v) s = s.split('{'+x+'}').join(v[x]);
  return s;
}
function zoneName(c){
  const base = c.split('').map(ch=>t('d.'+ch));
  return base.join('-');
}
function setLang(l){
  LANG = l; document.documentElement.lang = l; document.documentElement.dir = RTL[l] ? 'rtl' : 'ltr';
  try{ localStorage.setItem('vs.lang', l); }catch(e){}
}
